package lcdrill

// sumOfDistances returns, for every node, the sum of distances to all others.
func sumOfDistances(n int, edges [][]int) []int {
	if n <= 0 {
		return []int{}
	}
	head := make([]int, n)
	for i := range head {
		head[i] = -1
	}
	next := make([]int, 2*len(edges))
	to := make([]int, 2*len(edges))
	for i, e := range edges {
		u, v := e[0], e[1]
		to[2*i], next[2*i], head[u] = v, head[u], 2*i
		to[2*i+1], next[2*i+1], head[v] = u, head[v], 2*i+1
	}

	order := make([]int, 0, n)
	parent := make([]int, n)
	parent[0] = -1
	seen := make([]bool, n)
	seen[0] = true
	order = append(order, 0)
	for i := 0; i < len(order); i++ {
		u := order[i]
		for e := head[u]; e != -1; e = next[e] {
			v := to[e]
			if !seen[v] {
				seen[v] = true
				parent[v] = u
				order = append(order, v)
			}
		}
	}

	size := make([]int, n)
	ans := make([]int, n)
	for i := len(order) - 1; i >= 1; i-- {
		v := order[i]
		size[v]++
		size[parent[v]] += size[v]
		ans[parent[v]] += ans[v] + size[v]
	}
	size[0]++
	for i := 1; i < len(order); i++ {
		v := order[i]
		ans[v] = ans[parent[v]] + n - 2*size[v]
	}
	return ans
}
