import "testing"

// pascalRow is the O(n^2) triangle: correct, and far too slow for the sizes
// the last two tests use.
func pascalRow(n, p int) []int {
	row := []int{1 % p}
	for i := 1; i <= n; i++ {
		next := make([]int, i+1)
		next[0], next[i] = 1%p, 1%p
		for k := 1; k < i; k++ {
			next[k] = (row[k-1] + row[k]) % p
		}
		row = next
	}
	return row
}

func powMod(b, e, p int) int {
	r := 1 % p
	b %= p
	for e > 0 {
		if e&1 == 1 {
			r = r * b % p
		}
		b = b * b % p
		e >>= 1
	}
	return r
}

func TestBinomialRowMatchesPascal(t *testing.T) {
	for _, p := range []int{1000000007, 998244353, 10007} {
		for n := 0; n <= 80; n++ {
			got, want := binomialRow(n, p), pascalRow(n, p)
			if len(got) != len(want) {
				t.Fatalf("n=%d p=%d: got %d values, want %d", n, p, len(got), len(want))
			}
			for k := range want {
				if got[k] != want[k] {
					t.Fatalf("n=%d p=%d: C(%d,%d) = %d, want %d", n, p, n, k, got[k], want[k])
				}
			}
		}
	}
}

func TestBinomialRowMediumMatchesPascal(t *testing.T) {
	const n, p = 3000, 1000000007
	got, want := binomialRow(n, p), pascalRow(n, p)
	if len(got) != n+1 {
		t.Fatalf("got %d values, want %d", len(got), n+1)
	}
	for k := range want {
		if got[k] != want[k] {
			t.Fatalf("C(%d,%d) = %d, want %d", n, k, got[k], want[k])
		}
	}
}

// TestBinomialRowLarge is the size that rules out the triangle: n = 1000000
// makes Pascal roughly 5*10^11 additions, while the identities checked here
// pin the row down without ever building it.
func TestBinomialRowLarge(t *testing.T) {
	const n, p = 1000000, 1000000007
	row := binomialRow(n, p)
	if len(row) != n+1 {
		t.Fatalf("got %d values, want %d", len(row), n+1)
	}
	if row[0] != 1 || row[n] != 1 {
		t.Fatalf("ends are %d and %d, want 1 and 1", row[0], row[n])
	}
	if row[1] != n%p || row[n-1] != n%p {
		t.Fatalf("C(n,1) = %d and C(n,n-1) = %d, want %d", row[1], row[n-1], n%p)
	}
	for _, k := range []int{2, 3, 17, 4999, 250000, 499999, 500000} {
		if row[k] != row[n-k] {
			t.Fatalf("C(%d,%d) = %d but C(%d,%d) = %d", n, k, row[k], n, n-k, row[n-k])
		}
	}
	// Sum of the row is 2^n, and the alternating sum is 0 for n >= 1.
	sum, alt := 0, 0
	for k, v := range row {
		if v < 0 || v >= p {
			t.Fatalf("C(%d,%d) = %d is not reduced mod %d", n, k, v, p)
		}
		sum = (sum + v) % p
		if k%2 == 0 {
			alt = (alt + v) % p
		} else {
			alt = (alt - v + p) % p
		}
	}
	if want := powMod(2, n, p); sum != want {
		t.Fatalf("row sums to %d, want 2^n = %d", sum, want)
	}
	if alt != 0 {
		t.Fatalf("alternating sum is %d, want 0", alt)
	}
	// C(n,k) = C(n,k-1) * (n-k+1) / k has to hold everywhere, division being
	// multiplication by the inverse.
	for _, k := range []int{1, 2, 1000, 333333, n} {
		lhs := row[k] * k % p
		rhs := row[k-1] * ((n - k + 1) % p) % p
		if lhs != rhs {
			t.Fatalf("step from k=%d to %d breaks: %d != %d", k-1, k, lhs, rhs)
		}
	}
}

func TestBinomialRowLargeOtherPrime(t *testing.T) {
	const n, p = 700000, 998244353
	row := binomialRow(n, p)
	if len(row) != n+1 {
		t.Fatalf("got %d values, want %d", len(row), n+1)
	}
	sum := 0
	for _, v := range row {
		sum = (sum + v) % p
	}
	if want := powMod(2, n, p); sum != want {
		t.Fatalf("row sums to %d, want 2^n = %d", sum, want)
	}
	if row[0] != 1 || row[n] != 1 || row[1] != n%p {
		t.Fatalf("row starts %d, %d and ends %d", row[0], row[1], row[n])
	}
}
