func TestConvexHullRandomSmall(t *testing.T) {
	rng := rand.New(rand.NewSource(97))
	for trial := 0; trial < 500; trial++ {
		n := 1 + rng.Intn(14)
		points := make([][]int, n)
		for i := range points {
			points[i] = []int{rng.Intn(9) - 4, rng.Intn(9) - 4}
		}
		hull := convexHull(points)
		d := distinctSorted(points)
		flat := true
		for _, p := range d {
			if len(d) >= 3 && cross2(d[0], d[len(d)-1], p) != 0 {
				flat = false
				break
			}
		}
		if len(d) < 3 || flat {
			want := d
			if len(d) > 2 {
				want = [][]int{d[0], d[len(d)-1]}
			}
			if !samePoints(hull, want) {
				t.Fatalf("degenerate input %v: got %v, want %v", points, hull, want)
			}
			continue
		}
		checkHull(t, points, hull)
	}
}

// TestConvexHullOnParabola is the size test: every one of the 300001 points is
// a hull vertex, so a gift-wrapping march costs O(n^2) and takes minutes. The
// expected answer is exact because no three points on y = x^2 are collinear:
// the lower chain is the whole parabola left to right, and the top edge closes
// it with no vertices in between.
func TestConvexHullOnParabola(t *testing.T) {
	const m = 150000
	points := make([][]int, 0, 2*m+1)
	for x := -m; x <= m; x++ {
		points = append(points, []int{x, x * x})
	}
	want := make([][]int, len(points))
	copy(want, points)
	rand.New(rand.NewSource(5)).Shuffle(len(points), func(i, j int) {
		points[i], points[j] = points[j], points[i]
	})
	got := convexHull(points)
	if len(got) != len(want) {
		t.Fatalf("got %d vertices, want %d", len(got), len(want))
	}
	if !samePoints(got, want) {
		for i := range want {
			if got[i][0] != want[i][0] || got[i][1] != want[i][1] {
				t.Fatalf("vertex %d is (%d,%d), want (%d,%d)", i, got[i][0], got[i][1], want[i][0], want[i][1])
			}
		}
	}
}

// TestConvexHullOnSquareCloud has a known four-vertex answer buried under
// 200000 interior points and 2000 points sitting on the edges, which must be
// dropped rather than reported.
func TestConvexHullOnSquareCloud(t *testing.T) {
	const m = 1000000
	rng := rand.New(rand.NewSource(11))
	points := [][]int{{m, m}, {-m, -m}, {m, -m}, {-m, m}}
	for i := 0; i < 200000; i++ {
		points = append(points, []int{rng.Intn(2*m-1) - (m - 1), rng.Intn(2*m-1) - (m - 1)})
	}
	for i := 0; i < 1000; i++ {
		x := rng.Intn(2*m-1) - (m - 1)
		points = append(points, []int{x, -m}, []int{-m, x})
	}
	rng.Shuffle(len(points), func(i, j int) { points[i], points[j] = points[j], points[i] })
	want := [][]int{{-m, -m}, {m, -m}, {m, m}, {-m, m}}
	if got := convexHull(points); !samePoints(got, want) {
		t.Fatalf("got %v, want %v", got, want)
	}
}
